from pathlib import Path

path = Path('src/pages/CoachAppWhiteboardStage2.tsx')
text = path.read_text()

text = text.replace(
"import { ArrowLeft, ChevronDown, ChevronUp, Copy, Eraser, Highlighter, Library, MousePointer2, Pause, Pencil, Play, Plus, Presentation, Redo2, Repeat2, Save, Share2, Cloud, History, Download, Users, BarChart3, Radio, Mic, Video, Film, BrainCircuit, GitCompare, Target, BookOpen, Sparkles, Trash2, Undo2, X } from 'lucide-react'",
"import { ArrowLeft, ChevronDown, ChevronUp, Circle, Copy, Eraser, Highlighter, Library, Minus, MousePointer2, Pause, Pencil, Play, Plus, Presentation, Redo2, Repeat2, Save, Share2, Cloud, History, Download, Users, BarChart3, Radio, Mic, Video, Film, BrainCircuit, GitCompare, Target, BookOpen, Sparkles, Square, Triangle, Trash2, Undo2, X } from 'lucide-react'"
)
text = text.replace(
"type Tool='MOVE'|'PEN'|'HIGHLIGHT'|'ARROW'|'ERASER'\ntype Point={x:number;y:number}\ntype Stroke={id:string;tool:'PEN'|'HIGHLIGHT'|'ARROW';points:Point[];width?:number;opacity?:number}",
"type DrawingTool='PEN'|'LINE'|'HIGHLIGHT'|'ARROW'|'CIRCLE'|'SQUARE'|'TRIANGLE'\ntype Tool='MOVE'|DrawingTool|'ERASER'\ntype Point={x:number;y:number}\ntype Stroke={id:string;tool:DrawingTool;points:Point[];width?:number;opacity?:number}"
)

anchor = "const clonePlay=(value:PlayState):PlayState=>structuredClone(value)\n"
helper = """const shapePoints=(tool:DrawingTool,start:Point,end:Point):Point[]=>{\n  if(tool==='LINE'||tool==='ARROW')return[start,end]\n  if(tool==='CIRCLE'){\n    const cx=(start.x+end.x)/2,cy=(start.y+end.y)/2,rx=Math.max(.5,Math.abs(end.x-start.x)/2),ry=Math.max(.5,Math.abs(end.y-start.y)/2)\n    return Array.from({length:37},(_,index)=>{const angle=(Math.PI*2*index)/36;return{x:cx+Math.cos(angle)*rx,y:cy+Math.sin(angle)*ry}})\n  }\n  if(tool==='SQUARE'){\n    const sx=end.x>=start.x?1:-1,sy=end.y>=start.y?1:-1\n    const visualSize=Math.max(Math.abs(end.x-start.x)*1.6,Math.abs(end.y-start.y),2)\n    const x2=start.x+sx*(visualSize/1.6),y2=start.y+sy*visualSize\n    return[start,{x:x2,y:start.y},{x:x2,y:y2},{x:start.x,y:y2},start]\n  }\n  if(tool==='TRIANGLE'){\n    const sx=end.x>=start.x?1:-1,sy=end.y>=start.y?1:-1\n    const visualSize=Math.max(Math.abs(end.x-start.x)*1.6,Math.abs(end.y-start.y),2)\n    const x2=start.x+sx*(visualSize/1.6),y2=start.y+sy*visualSize\n    return[{x:(start.x+x2)/2,y:start.y},{x:x2,y:y2},{x:start.x,y:y2},{x:(start.x+x2)/2,y:start.y}]\n  }\n  return[start,end]\n}\n"""
if helper.strip() not in text:
    if anchor not in text: raise SystemExit('clonePlay anchor missing')
    text = text.replace(anchor, anchor + helper, 1)

text = text.replace("  const[playerDrawerOpen,setPlayerDrawerOpen]=useState(false)\n", "  const[playerDrawerOpen,setPlayerDrawerOpen]=useState(false)\n  const[drawTrayOpen,setDrawTrayOpen]=useState(false)\n", 1)

old_move = """    setDrawing(current=>{if(!current)return current;if(current.tool==='ARROW')return{...current,points:[current.points[0],p]};const last=current.points[current.points.length-1];if(last&&Math.hypot(last.x-p.x,last.y-p.y)<.3)return current;return{...current,points:[...current.points,p]}})"""
new_move = """    setDrawing(current=>{if(!current)return current;if(['LINE','ARROW','CIRCLE','SQUARE','TRIANGLE'].includes(current.tool))return{...current,points:shapePoints(current.tool,current.points[0],p)};const last=current.points[current.points.length-1];if(last&&Math.hypot(last.x-p.x,last.y-p.y)<.3)return current;return{...current,points:[...current.points,p]}})"""
if old_move not in text: raise SystemExit('move drawing block missing')
text = text.replace(old_move,new_move,1)

old_tools_start = "    {!presenting&&<aside className=\"tools\">"
old_tools_end = "</aside>}\n    {!presenting&&<div className=\"drawing-controls\">"
start = text.find(old_tools_start)
end = text.find(old_tools_end,start)
if start < 0 or end < 0: raise SystemExit('toolbar block missing')
# include old drawing-controls through its closing line
controls_end = text.find("</div>}\n", end + len(old_tools_end))
if controls_end < 0: raise SystemExit('drawing controls end missing')
controls_end += len("</div>}\n")
replacement = """    {!presenting&&<aside className=\"tools\"><button title=\"Select and move\" aria-label=\"Select and move players or drawings\" aria-pressed={tool==='MOVE'} className={tool==='MOVE'?'active':''} onClick={()=>{setTool('MOVE');setDrawTrayOpen(false)}}><MousePointer2/><span>Move</span></button><button title=\"Add players\" aria-label=\"Open player strip\" aria-pressed={playerDrawerOpen} className={playerDrawerOpen?'active':''} onClick={()=>{setPlayerDrawerOpen(value=>!value);setDrawTrayOpen(false)}}><Users/><span>Players</span></button><button title=\"Drawing tools\" aria-label=\"Open drawing tools\" aria-pressed={drawTrayOpen} className={drawTrayOpen?'active':''} onClick={()=>{setDrawTrayOpen(value=>!value);setPlayerDrawerOpen(false);if(tool==='MOVE')setTool('PEN')}}><Pencil/><span>Draw</span></button><hr/><button title=\"Undo\" aria-label=\"Undo last Whiteboard change\" disabled={!undo.length} onClick={undoAction}><Undo2/><span>Undo</span></button><button title=\"Redo\" aria-label=\"Redo Whiteboard change\" disabled={!redo.length} onClick={redoAction}><Redo2/><span>Redo</span></button><button title=\"Clear current frame\" aria-label=\"Clear players and drawings from current frame\" onClick={clearBoard}><Trash2/><span>Clear</span></button></aside>}\n    {!presenting&&drawTrayOpen&&<section className=\"draw-bottom-tray\"><div className=\"draw-tool-list\"><button className={tool==='PEN'?'active':''} onClick={()=>setTool('PEN')}><Pencil/><span>Pen</span></button><button className={tool==='LINE'?'active':''} onClick={()=>setTool('LINE')}><Minus/><span>Line</span></button><button className={tool==='ARROW'?'active':''} onClick={()=>setTool('ARROW')}><ArrowLeft className=\"arrow-tool\"/><span>Arrow</span></button><button className={tool==='HIGHLIGHT'?'active':''} onClick={()=>setTool('HIGHLIGHT')}><Highlighter/><span>Highlight</span></button><button className={tool==='CIRCLE'?'active':''} onClick={()=>setTool('CIRCLE')}><Circle/><span>Circle</span></button><button className={tool==='SQUARE'?'active':''} onClick={()=>setTool('SQUARE')}><Square/><span>Square</span></button><button className={tool==='TRIANGLE'?'active':''} onClick={()=>setTool('TRIANGLE')}><Triangle/><span>Triangle</span></button><button className={tool==='ERASER'?'active danger':''} onClick={()=>setTool('ERASER')}><Eraser/><span>Eraser</span></button></div><div className=\"draw-settings\"><div className=\"zoom-controls\"><button onClick={()=>zoomBoard(1)}>+</button><button onClick={()=>zoomBoard(-1)}>−</button><button onClick={resetZoom}>Fit</button></div>{tool!=='ERASER'&&<><label>Thickness<input type=\"range\" min=\"0.5\" max=\"4\" step=\"0.25\" value={brushWidth} onChange={e=>setBrushWidth(Number(e.target.value))}/><b>{brushWidth.toFixed(1)}</b></label><label>Opacity<input type=\"range\" min=\"20\" max=\"100\" step=\"5\" value={brushOpacity} onChange={e=>setBrushOpacity(Number(e.target.value))}/><b>{brushOpacity}%</b></label>}</div><button className=\"draw-close\" aria-label=\"Close drawing tools\" onClick={()=>{setDrawTrayOpen(false);setTool('MOVE')}}><X/></button></section>}\n"""
text = text[:start] + replacement + text[controls_end:]

css_anchor = "/* Whiteboard horizontal AFL workspace */"
css = """
/* Grouped Whiteboard drawing tools */
.draw-bottom-tray{position:fixed!important;z-index:88!important;left:74px!important;right:0!important;bottom:0!important;min-height:112px!important;padding:10px 12px!important;background:rgba(5,22,31,.98)!important;border-top:1px solid #2d5668!important;box-shadow:0 -18px 50px rgba(0,0,0,.42)!important;display:grid!important;grid-template-columns:minmax(0,1fr) auto 42px!important;align-items:center!important;gap:14px!important;animation:wb-player-tray-in .18s ease both!important}.draw-tool-list{display:flex!important;align-items:center!important;gap:7px!important;overflow-x:auto!important;padding-bottom:2px!important}.draw-tool-list button{min-width:68px!important;height:68px!important;padding:7px 8px!important;border:1px solid #31505f!important;border-radius:12px!important;background:#0c2633!important;color:#d7e5ec!important;display:flex!important;flex-direction:column!important;align-items:center!important;justify-content:center!important;gap:5px!important;font-size:9px!important;font-weight:900!important}.draw-tool-list button svg{width:22px!important;height:22px!important}.draw-tool-list button.active{background:#109ee8!important;border-color:#65d0ff!important;color:#fff!important;box-shadow:0 0 0 2px rgba(32,184,255,.2)!important}.draw-tool-list button.danger.active{background:#7a2632!important;border-color:#e45c6b!important}.draw-settings{display:grid!important;grid-template-columns:auto minmax(150px,220px) minmax(150px,220px)!important;align-items:center!important;gap:10px!important}.draw-settings label{display:grid!important;grid-template-columns:auto minmax(70px,1fr) 34px!important;align-items:center!important;gap:7px!important;color:#a8bbc5!important;font-size:9px!important;font-weight:900!important;text-transform:uppercase!important}.draw-settings input{accent-color:#20b8ff!important}.draw-settings b{color:#fff!important;text-align:right!important}.draw-close{width:42px!important;height:42px!important;padding:0!important;justify-content:center!important;border-radius:11px!important}.cawb2:has(.draw-bottom-tray) .legend{bottom:120px!important}@media(max-width:980px){.draw-bottom-tray{left:64px!important;grid-template-columns:minmax(0,1fr) 42px!important}.draw-settings{grid-column:1/-1!important;grid-template-columns:auto 1fr 1fr!important}.draw-close{grid-column:2!important;grid-row:1!important}.draw-tool-list{grid-column:1!important;grid-row:1!important}}@media(max-width:700px){.draw-bottom-tray{left:0!important;bottom:58px!important;min-height:170px!important;padding:8px!important}.draw-tool-list button{min-width:62px!important;height:62px!important}.draw-settings{grid-template-columns:auto 1fr!important}.draw-settings label:last-child{grid-column:2!important}.cawb2:has(.draw-bottom-tray) .legend{bottom:238px!important}}

"""
if css.strip() not in text:
    if css_anchor not in text: raise SystemExit('CSS anchor missing')
    text = text.replace(css_anchor, css + css_anchor, 1)

path.write_text(text)
